#!/usr/bin/env bash
# The terminal sessions quoted in lesson 23 of azure-operations, as a script that
# produces them. Its output is not committed; every transcript was copied from it.
#
#   bash lab.sh student && bash lab.sh tools   # once
#   bash captures.sh
#
# Resources and Perf are generated by the lesson's inventory.kql and perf.kql,
# in the shape of Azure Resource Graph's Resources table and Log Analytics' Perf
# table, and say so. The Resource Graph query runs in the Kusto emulator, not
# against Resource Graph; `az graph query` is shown in the lesson as not run.

HERE=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=../../capture.sh
. "$HERE/../../capture.sh"
student_env
kusto_up && kusto_db
kusto_load le-hmyb4w9b/idle.md:inventory.kql le-hmyb4w9b/rightsizing.md:perf.kql
cd "$HOME/azure/kusto" || exit 1

put idle.kql <<'KQL'
// idle.kql: resources that cost money and serve nothing
Resources
| where (type == "microsoft.compute/disks" and properties.diskState == "Unattached")
     or (type == "microsoft.network/publicipaddresses" and isempty(tostring(properties.ipConfiguration)))
     or (type == "microsoft.web/serverfarms" and toint(properties.numberOfSites) == 0)
| project name, type, resourceGroup, sku, owner = tostring(tags.team)
KQL
block idle
run 'python3 kql.py < idle.kql'

put rightsize.kql <<'KQL'
// rightsize.kql: CPU over two weeks, and what it would be on a VM with fewer vCPUs
Perf
| where CounterName == "% Processor Time"
| summarize avg_cpu = round(avg(CounterValue), 1), p95_cpu = round(percentile(CounterValue, 95), 1) by Computer, vcpus
| extend p95_on_half = round(p95_cpu * 2, 1), p95_on_quarter = round(p95_cpu * 4, 1)
| project Computer, vcpus, avg_cpu, p95_cpu, p95_on_half, p95_on_quarter
| order by p95_cpu asc
KQL
block rightsize
run 'python3 kql.py < rightsize.kql'
block reports
kq 'Perf | where Computer == "vm-reports" | summarize max_cpu = max(CounterValue), hours_over_5 = countif(CounterValue > 5)'
lab_down
